// Build the prompt for this customer
const c = $input.item.json;

const threadLines = (c.thread || []).map(t => {
  const parts = [];
  if (t.customer) parts.push(`Customer: ${t.customer}`);
  if (t.ai)       parts.push(`Swarnix AI: ${t.ai}`);
  if (t.feature)  parts.push(`[Feature used: ${t.feature}]`);
  return parts.join('\n');
}).join('\n---\n');

return {
  json: {
    phone: c.phone,
    name: c.name,
    msgCount: c.msgCount,
    firstAt: c.firstAt,
    lastAt: c.lastAt,
    prompt: `You are a business intelligence assistant for a premium Indian jewellery store using the Swarnix WhatsApp AI platform.

Write a warm, rich summary (4-6 sentences) of this customer's WhatsApp shopping journey so the jewellery store owner feels proud of their investment in Swarnix.

Guidelines:
- Highlight what jewellery categories/pieces the customer explored (rings, mangalsutra, necklaces, etc.)
- Mention any special features they used: voice search, image search, AI model try-on, virtual try-on
- Capture their engagement level and enthusiasm
- If they asked for specific occasions (wedding, anniversary, gifting), highlight it
- Frame it so the owner thinks: "Customers are really using and loving this!"
- Write in 3rd person, warm and professional tone
- Do NOT fabricate details not present in the conversation

Customer: ${c.name} (${c.phone})
Total messages: ${c.msgCount}
Period: ${c.firstAt} to ${c.lastAt}

Conversation:
${threadLines}

Respond with ONLY the summary paragraph.`
  }
};

// Extract summary text and pair back with customer identity
const customer = $('Build Prompt').item.json;
const content = $input.item.json.content;

// Claude returns content as an array of blocks or a plain string
let summary = '';
if (Array.isArray(content)) {
  summary = content.map(b => b.text || b).join(' ');
} else if (typeof content === 'string') {
  summary = content;
}

return {
  json: {
    phone: customer.phone,
    name: customer.name,
    summary: summary.trim()
  }
};
